[CODE] STEP 1, Open App.js. Replace the entire file with this:

 import { useState } from 'react';
 import { StatusBar } from 'expo-status-bar';
 import { StyleSheet, Text, TouchableOpacity, View } from 'react-native';

 function Glass({ filled, onPress }) {
 return (
 <TouchableOpacity style={styles.glass} onPress={onPress}>
 <Text style={styles.glassEmoji}>{filled ? '💧' : '⚪'}</Text>
 </TouchableOpacity>
 );
 }

 export default function App() {
 const [glasses, setGlasses] = useState([false, false, false, false, false, false, false, false]);
 const count = glasses.filter(g => g).length;

 const toggle = (i) => {
 const next = [...glasses];
 next[i] = !next[i];
 setGlasses(next);
 };

 return (
 <View style={styles.container}>
 <Text style={styles.title}>Hydra</Text>
 <Text style={styles.counter}>{count} / 8 glasses today</Text>
 <View style={styles.grid}>
 {glasses.map((filled, i) => (
 <Glass key={i} filled={filled} onPress={() => toggle(i)} />
 ))}
 </View>
 {count === 8 && <Text style={styles.celebrate}>✨ You hit 8 today.</Text>}
 <StatusBar style='auto' />
 </View>
 );
 }

 const styles = StyleSheet.create({
 container: { flex: 1, backgroundColor: '#e0f2fe', alignItems: 'center', justifyContent: 'center', padding: 20 },
 title: { fontSize: 36, fontWeight: 'bold', color: '#0c4a6e', marginBottom: 10 },
 counter: { fontSize: 18, color: '#075985', marginBottom: 30 },
 grid: { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'center', gap: 10, maxWidth: 320 },
